const items = $input.all();
const now = Date.now();
const readyItems = [];
for (const item of items) {
  const keys = Object.keys(item.json);
  if (keys.length === 0) continue;
  const bufferKey = keys[0];
  if (!bufferKey.startsWith('jarvis:buffer:')) continue;
  const bufferRaw = item.json[bufferKey];
  if (!bufferRaw || String(bufferRaw).trim() === '') continue;
  try {
    const bufferData = JSON.parse(String(bufferRaw));
    if (!bufferData.lastUpdatedMs || !bufferData.ttlSeconds) continue;
    if ((now - bufferData.lastUpdatedMs) >= bufferData.ttlSeconds * 1000) {
      const parts = bufferKey.split(':');
      readyItems.push({ json: {
        bufferKey: bufferKey,
        bufferData: bufferData,
        chatId: parseInt(parts[2]) || 0,
        userId: parseInt(parts[3]) || 0,
        fragmentCount: bufferData.fragments ? bufferData.fragments.length : 0
      }});
    }
  } catch(e) { /* skip malformed */ }
}
return readyItems;

const items = $input.all();
const outputItems = [];
for (const item of items) {
  const bufferData = item.json.bufferData;
  const chatId = item.json.chatId;
  const userId = item.json.userId;
  const bufferKey = item.json.bufferKey;
  if (!bufferData || !bufferData.fragments || bufferData.fragments.length === 0) continue;
  const fragments = bufferData.fragments;
  const textFragments = fragments.filter(function(f) { return f.type === 'text'; });
  const photoFragments = fragments.filter(function(f) { return f.type === 'photo'; });
  const voiceFragments = fragments.filter(function(f) { return f.type === 'voice'; });
  const combinedText = textFragments.map(function(f) { return f.content || ''; }).filter(Boolean).join(' ');
  let messageType = 'text';
  let finalContent = combinedText;
  let fileId = null;
  if (photoFragments.length > 0) {
    messageType = 'photo';
    const photoWithCtx = photoFragments.find(function(f) { return !f.awaitingContext && f.contextText; });
    const firstPhoto = photoFragments[0];
    fileId = firstPhoto.fileId;
    if (photoWithCtx) finalContent = photoWithCtx.contextText || combinedText;
    else if (firstPhoto.awaitingContext) finalContent = '__foto_sin_contexto__';
    else finalContent = firstPhoto.caption || combinedText || '';
  } else if (voiceFragments.length > 0) {
    messageType = 'voice';
    fileId = voiceFragments[0].fileId;
    finalContent = '';
  }
  outputItems.push({ json: {
    bufferKey: bufferKey,
    chatId: chatId,
    userId: userId,
    messageType: messageType,
    content: finalContent,
    fileId: fileId || null,
    fragmentCount: fragments.length
  }});
}
return outputItems;

